@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private string statusFilter = "";
    private bool showCreateForm;
    private ShipmentDto newShipment = new();
    private string? createError;
    private int? editingId;
    private ShipmentStatus editStatus;

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? []).Where(s =>
        {
            if (!string.IsNullOrWhiteSpace(filterText))
            {
                var f = filterText.Trim();
                if (!s.TrackingNumber.Contains(f, StringComparison.OrdinalIgnoreCase) &&
                    !s.Destination.Contains(f, StringComparison.OrdinalIgnoreCase))
                    return false;
            }
            if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var st))
            {
                if (s.Status != st) return false;
            }
            return true;
        });

    protected override async Task OnInitializedAsync()
    {
        await LoadShipments();
    }

    private async Task LoadShipments()
    {
        try
        {
            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments");
        }
        catch
        {
            shipments = [];
        }
    }

    private void ShowCreateForm() => showCreateForm = true;
    private void CancelCreate() { showCreateForm = false; createError = null; }

    private async Task CreateShipment()
    {
        createError = null;
        var response = await Http.PostAsJsonAsync("/api/shipments", newShipment);
        if (response.IsSuccessStatusCode)
        {
            showCreateForm = false;
            newShipment = new();
            await LoadShipments();
        }
        else
        {
            createError = $"Failed to create shipment: {response.StatusCode}";
        }
    }

    private void StartEdit(ShipmentDto s)
    {
        editingId = s.Id;
        editStatus = s.Status;
    }

    private void CancelEdit() => editingId = null;

    private async Task SaveEdit(ShipmentDto s)
    {
        s.Status = editStatus;
        await Http.PutAsJsonAsync($"/api/shipments/{s.Id}", s);
        editingId = null;
        await LoadShipments();
    }

    private static string GetStatusBadge(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "bg-secondary",
        ShipmentStatus.PickedUp => "bg-info text-dark",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-warning text-dark",
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.Cancelled => "bg-danger",
        _ => "bg-secondary"
    };
}

