+                        <dd>@shipment.Destination</dd>
+                    </dl>
+                </div>
+                <div class="col-md-6">
+                    <dl>
+                        <dt>Shipped Date</dt>
+                        <dd>@shipment.CreatedDate.ToString("MMM dd, yyyy")</dd>
+                        <dt>Estimated Delivery</dt>
+                        <dd>
+                            @if (shipment.EstimatedDelivery.HasValue)
+                            {
+                                <strong>@shipment.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</strong>
+                                @if (shipment.Status != ShipmentStatus.Delivered && shipment.Status != ShipmentStatus.Cancelled)
+                                {
+                                    var daysLeft = (shipment.EstimatedDelivery.Value.Date - DateTime.UtcNow.Date).Days;
+                                    if (daysLeft > 0)
+                                    {
+                                        <span class="text-muted"> (@daysLeft day(s) away)</span>
+                                    }
+                                    else if (daysLeft == 0)
+                                    {
+                                        <span class="text-success"> (Today!)</span>
+                                    }
+                                    else
+                                    {
+                                        <span class="text-danger"> (Overdue)</span>
+                                    }
+                                }
+                            }
+                            else
+                            {
+                                <span>—</span>
+                            }
+                        </dd>
+                        @if (!string.IsNullOrEmpty(shipment.Notes))
+                        {
+                            <dt>Notes</dt>
+                            <dd>@shipment.Notes</dd>
+                        }
