+@page "/my-shipments"
+@using Microsoft.AspNetCore.Authorization
+@using ShipmentTracker.Client.Models
+@attribute [Authorize]
+@inject HttpClient Http
+@inject NavigationManager Navigation
+
+<PageTitle>My Shipments</PageTitle>
+
+<h1>My Shipments</h1>
+
+<div class="row mb-3">
+    <div class="col-md-4">
+        <select class="form-select" @bind="statusFilter">
+            <option value="">All Statuses</option>
+            @foreach (var s in Enum.GetValues<ShipmentStatus>())
+            {
+                <option value="@s">@s</option>
+            }
+        </select>
+    </div>
+    <div class="col-md-2">
+        <button class="btn btn-outline-secondary" @onclick="LoadShipments">Refresh</button>
+    </div>
+</div>
+
+@if (shipments == null)
+{
+    <p><em>Loading your shipments...</em></p>
+}
+else if (!FilteredShipments.Any())
+{
+    <p>No shipments found.</p>
+}
+else
+{
+    <div class="row">
+        @foreach (var s in FilteredShipments)
+        {
+            <div class="col-md-6 col-lg-4 mb-3">
+                <div class="card h-100 @(s.Status == ShipmentStatus.Delivered ? "border-success" : "")">
+                    <div class="card-body">
+                        <h6 class="card-title">@s.TrackingNumber</h6>
+                        <p class="card-text mb-1">
+                            <span class="badge @GetStatusBadge(s.Status)">@s.Status</span>
+                        </p>
+                        <p class="card-text mb-1"><small class="text-muted">@s.Origin → @s.Destination</small></p>
+                        @if (s.EstimatedDelivery.HasValue)
+                        {
+                            <p class="card-text"><small>Est. delivery: <strong>@s.EstimatedDelivery.Value.ToString("MMM dd, yyyy")</strong></small></p>
+                        }
+                    </div>
+                    <div class="card-footer">
+                        <button class="btn btn-sm btn-outline-primary" @onclick="() => ViewDetails(s.TrackingNumber)">
+                            View Details
+                        </button>
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private List<ShipmentDto>? shipments;
+    private string statusFilter = "";
+
+    private IEnumerable<ShipmentDto> FilteredShipments =>
+        (shipments ?? []).Where(s =>
+        {
+            if (!string.IsNullOrWhiteSpace(statusFilter) && Enum.TryParse<ShipmentStatus>(statusFilter, out var st))
+                return s.Status == st;
+            return true;
+        });
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadShipments();
+    }
+
+    private async Task LoadShipments()
+    {
+        try
+        {
+            shipments = await Http.GetFromJsonAsync<List<ShipmentDto>>("/api/shipments/my");
+        }
+        catch
+        {
+            shipments = [];
+        }
+    }
+
+    private void ViewDetails(string trackingNumber)
+    {
+        Navigation.NavigateTo($"/track/{trackingNumber}");
+    }
+
+    private static string GetStatusBadge(ShipmentStatus status) => status switch
