public class ApplicationDbContext(DbContextOptions<ApplicationDbContext> options) : IdentityDbContext<ApplicationUser>(options)
{
    public DbSet<Shipment> Shipments => Set<Shipment>();

    protected override void OnModelCreating(ModelBuilder builder)
    {
        base.OnModelCreating(builder);

        builder.Entity<Shipment>(e =>
        {
            e.HasIndex(s => s.TrackingNumber).IsUnique();
            e.HasIndex(s => s.CustomerEmail);
        });
    }
}

builder.Services.AddAuthorizationCore();
builder.Services.AddCascadingAuthenticationState();
builder.Services.AddAuthenticationStateDeserialization();

builder.Services.AddScoped(sp =>
    new HttpClient { BaseAddress = new Uri(builder.HostEnvironment.BaseAddress) });

app.MapAdditionalIdentityEndpoints();

var shipments = app.MapGroup("/api/shipments").RequireAuthorization();

// GET all shipments (dispatchers only)
shipments.MapGet("/", async (ApplicationDbContext db) =>
{
    var list = await db.Shipments.OrderByDescending(s => s.CreatedDate).ToListAsync();
    return list.Select(s => new ShipmentTracker.Client.Models.ShipmentDto
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentTracker.Client.Models.ShipmentStatus)s.Status,
        CreatedDate = s.CreatedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Notes = s.Notes
    });
}).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

// GET shipment by tracking number (any visitor)
shipments.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var s = await db.Shipments.FirstOrDefaultAsync(x => x.TrackingNumber == trackingNumber);
    if (s is null) return Results.NotFound();
    return Results.Ok(new ShipmentTracker.Client.Models.ShipmentDto
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentTracker.Client.Models.ShipmentStatus)s.Status,
        CreatedDate = s.CreatedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Notes = s.Notes
    });
}).AllowAnonymous();

// GET shipments for current customer
shipments.MapGet("/my", async (ApplicationDbContext db, HttpContext httpContext) =>
{
    var email = httpContext.User.Identity?.Name ?? "";
    var list = await db.Shipments.Where(s => s.CustomerEmail == email)
        .OrderByDescending(s => s.CreatedDate).ToListAsync();
    return list.Select(s => new ShipmentTracker.Client.Models.ShipmentDto
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = (ShipmentTracker.Client.Models.ShipmentStatus)s.Status,
        CreatedDate = s.CreatedDate,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Notes = s.Notes
    });
});

// POST create shipment (dispatchers only)
shipments.MapPost("/", async (ShipmentTracker.Client.Models.ShipmentDto dto, ApplicationDbContext db) =>
{
    var entity = new ShipmentTracker.Data.Shipment
    {
        TrackingNumber = dto.TrackingNumber,
        Origin = dto.Origin,
        Destination = dto.Destination,
        Status = (int)dto.Status,
        CreatedDate = DateTime.UtcNow,
        EstimatedDelivery = dto.EstimatedDelivery,
        CustomerEmail = dto.CustomerEmail,
        Notes = dto.Notes
    };
    db.Shipments.Add(entity);
    await db.SaveChangesAsync();
    dto.Id = entity.Id;
    dto.CreatedDate = entity.CreatedDate;
    return Results.Created($"/api/shipments/track/{entity.TrackingNumber}", dto);
}).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

// PUT update shipment status (dispatchers only)
shipments.MapPut("/{id}", async (int id, ShipmentTracker.Client.Models.ShipmentDto dto, ApplicationDbContext db) =>
{
    var entity = await db.Shipments.FindAsync(id);
    if (entity is null) return Results.NotFound();
    entity.Status = (int)dto.Status;
    entity.EstimatedDelivery = dto.EstimatedDelivery;
    entity.Notes = dto.Notes;
    entity.Destination = dto.Destination;
    entity.Origin = dto.Origin;
    entity.CustomerEmail = dto.CustomerEmail;
    await db.SaveChangesAsync();
    return Results.Ok();
}).RequireAuthorization(policy => policy.RequireRole("Dispatcher"));

await SeedData.InitializeAsync(app.Services);

app.Run();

